export const generateQRCodeDataURL = (text) => {
  try {
    const canvas = document.createElement('canvas');
    canvas.width = 200;
    canvas.height = 200;
    const ctx = canvas.getContext('2d');
    
    if (!ctx) {
      throw new Error('No se pudo obtener el contexto del canvas');
    }
    
    // Fondo blanco
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    // Código QR simulado (texto centrado)
    ctx.fillStyle = 'black';
    ctx.font = 'bold 16px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    
    // Dibujar código QR simulado
    ctx.fillText('QR CODE', canvas.width / 2, canvas.height / 2 - 20);
    
    ctx.font = 'bold 14px Arial';
    ctx.fillText(text, canvas.width / 2, canvas.height / 2 + 10);
    
    // Borde decorativo
    ctx.strokeStyle = '#4f46e5';
    ctx.lineWidth = 3;
    ctx.strokeRect(10, 10, canvas.width - 20, canvas.height - 20);
    
    // Patrón de puntos simulando QR
    ctx.fillStyle = '#4f46e5';
    for (let i = 0; i < 5; i++) {
      for (let j = 0; j < 5; j++) {
        if ((i + j) % 2 === 0) {
          ctx.fillRect(40 + i * 25, 40 + j * 25, 15, 15);
        }
      }
    }
    
    console.log('QR generado para:', text);
    return canvas.toDataURL('image/png');
  } catch (error) {
    console.error('Error generando QR:', error);
    // Fallback: crear una imagen simple
    return createFallbackQR(text);
  }
};

const createFallbackQR = (text) => {
  const canvas = document.createElement('canvas');
  canvas.width = 200;
  canvas.height = 200;
  const ctx = canvas.getContext('2d');
  
  // Fondo gradiente
  const gradient = ctx.createLinearGradient(0, 0, 200, 200);
  gradient.addColorStop(0, '#4f46e5');
  gradient.addColorStop(1, '#7c3aed');
  
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 200, 200);
  
  ctx.fillStyle = 'white';
  ctx.font = 'bold 16px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('CÓDIGO QR', 100, 80);
  
  ctx.font = 'bold 18px Arial';
  ctx.fillText(text, 100, 120);
  
  return canvas.toDataURL('image/png');
};

